/** The Glance mark: a list row pulled into a reading panel. Painted from the accent tokens. */
function glance_mark(): string
{
    return '<svg class="glance-mark" viewBox="0 0 48 48" width="32" height="32" aria-hidden="true" focusable="false">'
        . '<rect width="48" height="48" rx="12" style="fill:var(--accent)"/>'
        . '<rect x="9" y="11.5" width="12" height="5" rx="2.5" style="fill:var(--accent-ink);fill-opacity:.45"/>'
        . '<rect x="9" y="31.5" width="12" height="5" rx="2.5" style="fill:var(--accent-ink);fill-opacity:.45"/>'
        . '<path d="M11.5 21.5H22a3 3 0 0 0 3-3V12a3 3 0 0 1 3-3h8a3 3 0 0 1 3 3v24a3 3 0 0 1-3 3h-8a3 3 0 0 1-3-3v-6.5a3 3 0 0 0-3-3H11.5a2.5 2.5 0 0 1 0-5Z" style="fill:var(--accent-ink)"/>'
        . '</svg>';
}

/** An inline icon. Decorative unless a label is given. */
function glance_icon(string $name, string $label = ''): string
{
    $paths = glance_icon_paths()[$name] ?? '';
    $a11y  = $label === '' ? 'aria-hidden="true"' : 'role="img" aria-label="' . osc_esc_html($label) . '"';

    return '<svg class="gi gi-' . $name . '" ' . $a11y . ' viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" focusable="false">' . $paths . '</svg>';
}
